import { Component, ChangeDetectionStrategy, computed, inject, input } from '@angular/core';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';

/**
 * Inline-SVG icon set, currentColor. Stroked icons sit on a 24×24 viewBox
 * with a ~1.5px stroke; solid ones fill their own viewBox.
 *
 * The game's only icon set: every view uses <td-icon>. Many shapes come from
 * Lucide (ISC), Tabler (MIT), Phosphor (MIT) and game-icons.net (CC BY 3.0),
 * the source named on each line; see the attributions.
 *
 * Usage: `<td-icon name="heart" size="20" />`
 *
 * Implementation note: rendering SVG markup via [innerHTML] requires the host
 * element to NOT be an <svg> itself — otherwise the parsed children land in
 * the HTML namespace instead of SVG. We use a `<span>` host and embed the
 * full <svg>...</svg> string. SVG bodies are author-controlled (no user input)
 * so DomSanitizer.bypassSecurityTrustHtml is safe.
 */
export type TdIconName =
  | 'heart' | 'coin' | 'wave' | 'sword' | 'tower' | 'target' | 'bolt' | 'flame'
  | 'flask' | 'shield' | 'skull' | 'bug' | 'pin' | 'flag' | 'home' | 'search'
  | 'caret' | 'caretL' | 'caretR' | 'caretU' | 'play' | 'pause' | 'stop' | 'power'
  | 'cog' | 'eye' | 'eyeOff' | 'speed' | 'fullscreen' | 'layers' | 'grid'
  | 'audio' | 'audioOff' | 'music' | 'build' | 'refresh' | 'text' | 'bulb' | 'user'
  | 'sliders' | 'chart' | 'share' | 'filing' | 'case' | 'cross' | 'close' | 'check'
  | 'info' | 'warn' | 'random' | 'manual' | 'edit'
  // additions for full mat-icon migration
  | 'lock' | 'bookmark' | 'plus' | 'minus' | 'terrain' | 'copyright'
  | 'vibration' | 'fastForward' | 'gamepad' | 'trash' | 'copy' | 'dragHandle'
  | 'externalLink' | 'download' | 'mouseLeft' | 'mouseRight' | 'mouseWheel' | 'shuffle' | 'arrowUp' | 'walk' | 'run'
  | 'splash' | 'route' | 'undo' | 'wind' | 'gridAir' | 'radiation' | 'plane' | 'ghost' | 'camera' | 'moon'
  // damage types without an icon of their own (DAMAGE_TYPE_ICON)
  | 'sparkle' | 'snowflake' | 'burst'
  // world map
  | 'globe'
  // veteran rank insignia
  | 'chevrons2' | 'chevrons3' | 'star'
  // orbital laser ability
  | 'laser'
  // research tree, glyphs from the research-tree design
  | 'gatling' | 'iceStar' | 'helix' | 'catapult' | 'flak' | 'arcaneStar' | 'tentacle' | 'hazardCone' | 'rocket' | 'frostRune' | 'rift' | 'mushroom' | 'pulse' | 'cogRing'
  // replay of the last wave
  | 'replay'
  // shortcut overview (sidebar footer)
  | 'keyboard'
  // coop (header, lobby dock, squad)
  | 'users'
  | 'link'
  | 'send'
  | 'more'
  | 'signIn'
  // header actions (design 2026-10-04): favourites, random place, HQ, spawn portal, a spawn more, coop
  | 'bookmarkStar' | 'dice' | 'castle' | 'portal' | 'portalAdd' | 'shields'
  // header stat plates, filled
  | 'hqSolid' | 'coinSolid' | 'waveSolid'
  // NEXT marks in the WAVE panel: ground, air, camouflaged wave
  | 'nextGround' | 'nextAir' | 'nextCamo';

interface IconDef {
  /** Inner SVG markup. Stroke uses currentColor; fill defaults to none unless set explicitly per <path>. */
  body: string;
  /** Optional override for fill mode (default 'none' — stroked icon). */
  fill?: 'none' | 'currentColor';
  /** Side of a square viewBox when not 24 (game-icons 512, Phosphor 256). */
  viewBox?: number;
  /** Filled shape without stroke, so the stroke width does not thicken it. */
  solid?: true;
}

