@Component({
  selector: 'td-icon',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `<span [innerHTML]="svgMarkup()"></span>`,
  styles: [`
    :host {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      line-height: 0;
    }
    :host > span {
      display: inline-flex;
    }
    :host ::ng-deep svg {
      display: block;
    }
  `],
})
export class TdIconComponent {
  private readonly sanitizer = inject(DomSanitizer);

  readonly name = input.required<TdIconName>();
  readonly size = input<number>(20);
  readonly strokeWidth = input<number>(1.5);
  readonly ariaLabel = input<string | null>(null);

  protected readonly svgMarkup = computed<SafeHtml>(() => {
    const def = ICONS[this.name()];
    const body = def?.body ?? '<circle cx="12" cy="12" r="6" />';
    const fill = def?.solid ? 'currentColor' : def?.fill ?? 'none';
    const stroke = def?.solid ? 'none' : 'currentColor';
    const vb = def?.viewBox ?? 24;
    const sz = this.size();
    const sw = this.strokeWidth();
    const aria = this.ariaLabel()
      ? ` role="img" aria-label="${this.ariaLabel()}"`
      : ' role="presentation"';
    const svg = `<svg width="${sz}" height="${sz}" viewBox="0 0 ${vb} ${vb}" fill="${fill}" stroke="${stroke}" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round"${aria}>${body}</svg>`;
    return this.sanitizer.bypassSecurityTrustHtml(svg);
  });
}
